'use strict';
(()=>{
 const G=JustinGame,game=window.justinClicker,stage=document.getElementById('stage'),button=document.createElement('button');button.id='backdrops-open';button.type='button';button.textContent='backdrops';document.querySelector('.nonsense-lab').append(button);
 const dialog=document.createElement('dialog');dialog.className='online-dialog backdrop-dialog';dialog.setAttribute('aria-label','Backdrop shop');dialog.innerHTML='<div class="online-dialog-head"><div><small>A CHANGE OF SCENERY</small><h2>put him somewhere else.</h2></div><button type="button" aria-label="Close backdrops">×</button></div><div class="backdrop-toolbar"><label>collection <select id="backdrop-group"><option value="all">all backdrops</option></select></label><strong id="backdrop-wallet"></strong></div><p class="backdrop-help">Cosmetic only. Buy once, switch whenever. Your clicking power stays the same.</p><div id="backdrop-grid"></div>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();
 const groups=[...new Set(G.backdrops.map(b=>b.group))];for(const group of groups){const o=document.createElement('option');o.value=group;o.textContent=group;document.getElementById('backdrop-group').append(o)}
 const site=document.createElement('div');site.id='site-backdrop';site.hidden=true;site.setAttribute('aria-hidden','true');const ambient=document.createElement('canvas');ambient.hidden=true;site.append(ambient);document.body.prepend(site);const ambientCtx=ambient.getContext('2d');let ambientAt=0;function resizeAmbient(){const scale=Math.min(1,1600/innerWidth,1200/innerHeight);ambient.width=Math.ceil(innerWidth*scale);ambient.height=Math.ceil(innerHeight*scale)}window.addEventListener('resize',resizeAmbient);resizeAmbient();const cards=new Map();let current='plain',generation=0,art=null,artW=0,artH=0;
 for(const b of G.backdrops){const card=document.createElement('article');card.className='backdrop-card';const image=document.createElement('div');image.className='backdrop-preview';if(b.thumb){const img=document.createElement('img');img.src=b.thumb;img.loading='lazy';img.decoding='async';img.alt=b.name;image.append(img)}else image.classList.add(b.animated?'preview-justinverse':'preview-plain');const name=document.createElement('b'),tag=document.createElement('small'),buy=document.createElement('button');name.textContent=b.name;tag.textContent=b.tag||b.group;buy.type='button';buy.onclick=()=>{game.backdropAction(b.id);render()};card.append(image,name,tag,buy);document.getElementById('backdrop-grid').append(card);cards.set(b.id,{card,buy})}
 function render(){const s=game.snapshot(),group=document.getElementById('backdrop-group').value;document.getElementById('backdrop-wallet').textContent=Math.floor(s.bank).toLocaleString()+' points';for(const b of G.backdrops){const {card,buy}=cards.get(b.id),owned=s.backdrops.includes(b.id),equipped=s.backdrop===b.id;card.hidden=group!=='all'&&b.group!==group;card.classList.toggle('is-equipped',equipped);buy.disabled=equipped||!owned&&(b.adminOnly||s.bank<b.cost);buy.textContent=equipped?'equipped':owned?'equip':b.adminOnly?'admin gift only':b.cost.toLocaleString()+' points';buy.setAttribute('aria-label',equipped?'Equipped '+b.name:owned?'Equip backdrop '+b.name:b.adminOnly?b.name+' is only available as an admin gift':'Buy backdrop '+b.name+' for '+b.cost+' points')}}
 button.onclick=()=>{render();dialog.showModal()};document.getElementById('backdrop-group').onchange=render;setInterval(()=>{if(dialog.open&&!document.hidden)render()},500);
 function sync(s){const next=s.backdrop||'plain';if(next===current)return;current=next;generation++;ambientAt=0;stage.classList.toggle('has-backdrop',next!=='plain');document.body.classList.toggle('has-site-backdrop',next!=='plain');site.hidden=next==='plain';ambient.hidden=next!=='justinverse';site.style.backgroundImage='none';if(next==='plain'||next==='justinverse')return;const b=G.backdrops.find(b=>b.id===next);if(b?.src)site.style.backgroundImage='url("'+b.src+'")';}

 const stars=Array.from({length:50},(_,i)=>({x:((i*157+31)%997)/997,y:((i*263+89)%991)/991,size:i%4===0?2:1}));
 function draw(ctx,w,h,t,impact,gentle){if(current==='plain')return;if(current!=='justinverse')return;
  const time=gentle?0:t;if(!art||artW!==w||artH!==h){artW=w;artH=h;art=document.createElement('canvas');art.width=Math.ceil(w);art.height=Math.ceil(h);const c=art.getContext('2d'),g=c.createRadialGradient(w*.3,h*.25,0,w*.45,h*.4,w*.8);g.addColorStop(0,'#643a92');g.addColorStop(.45,'#17204f');g.addColorStop(1,'#050711');c.fillStyle=g;c.fillRect(0,0,w,h)}ctx.drawImage(art,0,0,w,h);ctx.save();for(const s of stars){ctx.globalAlpha=.4+.4*Math.sin(time*.5+s.x*6)**2;ctx.fillStyle=s.size===2?'#b6faff':'#fff';ctx.fillRect((s.x*w+time*(s.size===2?5:2))%w,s.y*h,s.size,s.size)}ctx.globalAlpha=.3;ctx.strokeStyle='#85baff';ctx.lineWidth=1;for(let i=0;i<5;i++){ctx.beginPath();ctx.ellipse(w*.5,h*.7,w*(.16+i*.075),h*(.06+i*.028),Math.sin(time*.15)*.1,0,Math.PI*2);ctx.stroke()}ctx.globalAlpha=.8;for(let i=0;i<3;i++){const a=time*.18+i*Math.PI*2/3,x=w*.5+Math.cos(a)*w*.34,y=h*.55+Math.sin(a)*h*.27;ctx.fillStyle=['#a7f4e8','#ffbbdc','#dfd27a'][i];ctx.beginPath();ctx.arc(x,y,7+i*3,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ffffff55';ctx.beginPath();ctx.ellipse(x,y,19+i*4,5+i, -.4,0,Math.PI*2);ctx.stroke()}ctx.globalAlpha=.7;ctx.fillStyle='#eee';ctx.font='10px monospace';ctx.fillText('THE JUSTIN DIMENSION / visitor parking only',14,h-22);ctx.restore();
 }
 function ambientFrame(ms){requestAnimationFrame(ambientFrame);if(current!=='justinverse'||document.hidden||document.querySelector('dialog[open]')||ms-ambientAt<32)return;const gentle=document.getElementById('gentle').checked;if(gentle&&ambientAt)return;ambientAt=ms;draw(ambientCtx,ambient.width,ambient.height,ms/1000,0,gentle)}window.JustinBackdrops={sync};sync(game.snapshot());requestAnimationFrame(ambientFrame);
})();
